<script setup>
import {tr,locale,setLanguage} from "./i18n";
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue';
import {version as appVersion} from '../package.json';
import {invoke} from '@tauri-apps/api/core';
import {listen} from '@tauri-apps/api/event';
import SetupGuide from './SetupGuide.vue';
import Diagnostics from './Diagnostics.vue';
import driveImage from './assets/drive.png';
import {HardDrive,RefreshCw,ArrowUpRight,ShieldCheck,BookOpen,Settings,Download,FolderOpen,LogOut,CheckCircle2} from 'lucide-vue-next';
const state=ref(null),page=ref('disks'),busy=ref(false),notice=ref(''),error=ref(false),backend=ref('Auto'),update=ref(null),updateStatus=ref('checking'),updateError=ref(''),updating=ref(false),progress=ref(0);
const autoMount=ref(true),theme=ref('Stone'),selected=ref('');
const updateText=computed(()=>updateStatus.value==='available'?tr('需要更新')+' '+update.value?.version:updateStatus.value==='latest'?tr('已是最新版本'):updateStatus.value==='offline'?tr('暂时无法检查更新，离线功能可继续使用'):updateStatus.value==='error'?tr('检查更新失败')+': '+updateError.value:tr('正在检查更新…'));
const required=computed(()=>state.value?.required_update||update.value);
watch(()=>required.value?.version,async version=>{if(version){await nextTick();document.querySelector('.update-gate button:not(:disabled)')?.focus();}});
const selectedVolume=computed(()=>state.value?.volumes.find(v=>v.uuid===selected.value)||state.value?.volumes[0]);
const visibleVolumes=computed(()=>theme.value!=='Stone'?(selectedVolume.value?[selectedVolume.value]:[]):state.value?.volumes||[]);
let timer,unlistenDevices,unlistenResult,unlistenUpdate,unlistenNavigate;
async function refresh(){try{state.value=await invoke('snapshot');backend.value=state.value.settings.backend;autoMount.value=state.value.settings.auto_mount;theme.value=state.value.settings.theme||'Stone';setLanguage(state.value.settings.language||'auto');}catch(e){show(e,true)}}
function show(message,isError=false){notice.value=String(message);error.value=isError}
async function act(action,volume=null){if(busy.value||state.value?.monitor.busy)return;busy.value=true;notice.value='';try{show(await invoke('operate',{action,volume,backend:backend.value}));}catch(e){show(e,true)}finally{busy.value=false;await refresh()}}
async function save(){try{await invoke('save_settings',{settings:{backend:backend.value,dark:theme.value==='Graphite',theme:theme.value,auto_mount:autoMount.value,language:locale.value}});await refresh()}catch(e){show(e,true);await refresh()}}
async function updates(quiet=false){try{update.value=await invoke('check_updates');updateStatus.value=update.value?'available':'latest';await refresh();}catch(e){updateStatus.value=quiet?'offline':'error';updateError.value=String(e)}}
async function installUpdate(){if(!required.value||busy.value||updating.value||state.value?.update_blockers)return;updating.value=true;progress.value=0;try{await invoke('install_update')}catch(e){show(tr('更新失败，请重试')+': '+tr(String(e)),true)}finally{updating.value=false}}
function size(n){return n?(n/1e9).toFixed(1)+' GB':'—'}
onMounted(async()=>{unlistenNavigate=await listen('navigate-settings',()=>{page.value='settings'});await refresh();unlistenDevices=await listen('devices-changed',()=>refresh());unlistenResult=await listen('operation-result',event=>{show(event.payload.message,event.payload.error);refresh()});unlistenUpdate=await listen('update-progress',event=>{const {received,total}=event.payload;progress.value=total?Math.round(received/total*100):0});updates(true);timer=setInterval(()=>{if(!busy.value)refresh()},8000)});onUnmounted(()=>{clearInterval(timer);unlistenDevices?.();unlistenResult?.();unlistenUpdate?.();unlistenNavigate?.()});
</script>
<template>
<div class="shell" :data-theme="theme">
<aside :inert="required?true:undefined"><div class="brand"><span class="logo"><img :src="driveImage" alt=""/></span><div>macntfs<small> {{tr(`磁盘，自由读写。`)}} </small></div></div><div class="nav-label"> {{tr(`工作空间`)}} </div><button :class="{active:page==='disks'}" @click="page='disks'"><HardDrive :size="18"/> {{tr(`我的磁盘`)}} </button><button class="setup-nav" @click="page='settings'"><BookOpen :size="18"/> {{tr(`首次使用向导`)}} </button><button :class="{active:page==='settings'}" @click="page='settings'"><Settings :size="18"/> {{tr(`设置与更新`)}} </button><div v-if="theme==='Graphite' && page==='disks'" class="device-nav"><div class="nav-label"> {{tr(`外置设备`)}} </div><button v-for="v in state?.volumes" :key="v.uuid" :class="{active:selectedVolume?.uuid===v.uuid}" @click="selected=v.uuid"><HardDrive :size="18"/><span>{{v.name||tr(`未命名磁盘`)}}<small>NTFS · {{v.id}}</small></span></button></div><div class="aside-footer"><span class="dot"></span> {{tr(`本地运行 · 离线可用`)}} <small> {{tr(`免费开源 / v`)}} {{state?.version||appVersion}}</small><small> {{tr(`作者 Lucky · 473276@qq.com`)}} </small></div></aside>
<main :inert="required?true:undefined"><header><div><span class="eyebrow">NTFS FOR MAC</span><h1>{{page==='disks'?tr(`我的磁盘`):tr(`设置与更新`)}}</h1><p>{{page==='disks'?tr(`连接外置 NTFS 磁盘，轻松管理读写。`):tr(`管理读写组件和 GitHub 版本更新。`)}}</p></div><div class="header-actions"><button class="secondary" @click="page='settings'"> {{tr(`首次使用向导`)}} </button><button class="secondary" @click="refresh" :disabled="busy"><RefreshCw :size="16"/> {{tr(`刷新`)}} </button></div></header>
<section v-if="state && (!state.environment.runtime||(backend!=='Microvm'&&!state.environment.fuse))" class="setup"><div class="icon"><ShieldCheck/></div><div><h3> {{tr(`完成读写组件安装`)}} </h3><p>{{!state.environment.runtime?tr(`安装或更新内置读写组件，即可继续使用。`):tr(`请安装内置 macFUSE，并完成 macOS 系统授权。`)}}</p><small> {{tr(`安装资源随软件提供，无需联网。`)}} </small></div><button class="primary" :disabled="busy" @click="act('install')"> {{tr(`安装组件`)}} <ArrowUpRight :size="16"/></button></section>
<section v-if="state && state.environment.runtime && !state.environment.service" class="setup"><div class="icon"><ShieldCheck/></div><div><h3> {{tr(`后台助手连接异常`)}} </h3><p>{{tr(state?.environment.service_issue||'')}}</p><small> {{tr(`已安装完整 PKG 时，请先退出旧版本和测试实例，再从「应用程序」启动。`)}} </small></div><button class="primary" :disabled="busy" @click="act('release')"> {{tr(`完整安装包`)}} <Download :size="16"/></button></section>
<section v-if="notice" class="notice" :class="{error}"><strong>{{tr(notice.split('\n')[0])}}</strong><button v-if="error && notice.includes('macOS 拒绝访问磁盘设备')" class="permission-button secondary" :disabled="busy" @click="act('permissions')"> {{tr(`打开磁盘访问权限设置`)}} <ArrowUpRight :size="15"/></button><button v-if="error && notice.includes('macOS 拒绝访问磁盘设备')" class="permission-button secondary" :disabled="busy" @click="act('permission-helper')"> {{tr(`打开助手位置`)}} <FolderOpen :size="15"/></button><details v-if="notice.includes('\n')"><summary> {{tr(`技术详情`)}} </summary><pre>{{notice.split('\n').slice(1).join('\n')}}</pre></details><button class="dismiss" @click="notice=''">×</button></section>
<template v-if="page==='disks'"><div class="section-title"><h2> {{tr(`外置磁盘`)}} <span>{{state?.volumes.length||0}}</span></h2><span>{{state?.monitor.busy?tr(`正在自动开启读写…`):tr(`实时设备检测`)}}</span></div><div v-if="theme==='Office' && state?.volumes.length" class="volume-table" role="group" :aria-label='tr(`外置磁盘列表`)'><div class="table-heading"><span> {{tr(`磁盘`)}} </span><span> {{tr(`文件系统`)}} </span><span> {{tr(`容量`)}} </span><span> {{tr(`状态`)}} </span></div><button v-for="v in state.volumes" :key="v.uuid" :class="{selected:selectedVolume?.uuid===v.uuid}" @click="selected=v.uuid"><span><HardDrive :size="20"/> {{v.name||tr(`未命名磁盘`)}}</span><span>NTFS</span><span>{{size(v.size)}}</span><span :class="{'table-writable':v.writable&&v.mount}">{{v.mount?(v.writable?tr(`可读写`):tr(`只读`)):tr(`未挂载`)}}</span></button></div><div class="service-line" v-if="state?.environment.service"><CheckCircle2 :size="15"/> {{tr(`后台助手已连接`)}} </div><div class="disk-workspace"><div class="disks"><article v-for="v in visibleVolumes" :key="v.uuid" class="disk"><div class="disk-heading"><div class="drive-icon"><img :src="driveImage" :alt='tr(`外置磁盘`)'/></div><div class="volume-title"><h3>{{v.name||tr(`未命名磁盘`)}}</h3><p class="device">NTFS · {{v.id}}</p></div><span class="badge" :class="{writable:v.writable&&v.mount}">{{v.mount?(v.writable?tr(`可读写`):tr(`只读`)):tr(`未挂载`)}}</span></div><div class="capacity"><strong>{{size(v.size)}}</strong><span> {{tr(`总容量`)}} </span></div><div class="disk-meta"><span> {{tr(`文件系统`)}} </span><span>NTFS</span></div><div class="disk-meta"><span> {{tr(`设备标识`)}} </span><span>{{v.id}}</span></div><div class="disk-meta"><span> {{tr(`挂载位置`)}} </span><span :title="v.mount">{{v.mount||tr(`尚未挂载`)}}</span></div><div class="actions"><button class="primary" :disabled="busy||updating" v-if="!v.writable||!v.mount" @click="act('mount',v)">{{busy?tr(`处理中…`):tr(`开启读写`)}}<ArrowUpRight :size="16"/></button><button class="primary" v-else :disabled="busy" @click="act('open',v)"><FolderOpen :size="16"/> {{tr(`打开 Finder`)}} </button><button class="eject secondary" :disabled="busy" @click="act('eject',v)" :title='tr(`安全推出整块磁盘，包括其他分区`)'><LogOut :size="17"/> {{tr(`安全推出`)}} </button></div></article></div><section class="quick-settings"><div v-if="theme==='Graphite' && selectedVolume" class="inspector-actions"><h3> {{tr(`操作`)}} </h3><button class="primary" :disabled="busy||state?.monitor.busy" @click="act(selectedVolume.mount&&selectedVolume.writable?'open':'mount',selectedVolume)">{{selectedVolume.mount&&selectedVolume.writable?tr(`打开 Finder`):tr(`开启读写`)}}</button><button class="secondary" :disabled="busy||state?.monitor.busy" @click="act('eject',selectedVolume)"> {{tr(`安全推出`)}} </button></div><div><h3> {{tr(`自动开启读写`)}} </h3><p>{{backend==='Microvm'?tr('实验模式仅手动挂载，暂停自动开启读写。'):tr('插入 NTFS 磁盘后自动连接。')}}</p></div><button class="switch" role="switch" :aria-checked="autoMount" :aria-label='tr(`自动开启读写`)' @click="autoMount=!autoMount;save()"><span></span></button><div class="quick-guide"><h3> {{tr(`首次使用向导`)}} </h3><p> {{tr(`按步骤完成系统授权。`)}} </p><button class="guide-link" @click="page='settings'"> {{tr(`查看指引`)}} <ArrowUpRight :size="14"/></button></div></section></div><section v-if="state&&!state.volumes.length" class="empty"><HardDrive :size="48"/><h3> {{tr(`等待连接磁盘`)}} </h3><p> {{tr(`连接 NTFS 格式的 USB 磁盘后，会自动显示在这里。`)}} </p></section><div class="tip"><ShieldCheck :size="17"/><span> {{tr(`磁盘休眠或文件系统异常时会停止开启读写，保护已有数据。`)}} </span></div></template>
<template v-else><section class="setting-card"><h2>{{tr(`语言`)}}</h2><div class="language-options"><button v-for="l in [{id:'auto',label:tr('跟随系统')},{id:'zh-Hans',label:'简体中文'},{id:'zh-Hant',label:'繁體中文'},{id:'en',label:'English'},{id:'ja',label:'日本語'}]" :key="l.id" :class="{selected:locale===l.id}" @click="setLanguage(l.id);save()">{{l.label}}</button></div></section><section class="setting-card"><h2> {{tr(`界面风格`)}} </h2><p> {{tr(`切换配色与布局，选择会自动保存。`)}} </p><div class="theme-options"><button v-for="t in [{id:'Stone',name:tr(`暖灰原生`),detail:tr(`浅色侧栏 · 石墨按钮`)},{id:'Office',name:tr(`简洁办公`),detail:tr(`顶部导航 · 钢蓝重点色`)},{id:'Graphite',name:tr(`深色工作台`),detail:tr(`设备侧栏 · 独立操作区`)}]" :key="t.id" :class="{selected:theme===t.id}" @click="theme=t.id;save()"><strong>{{t.name}}</strong><small>{{t.detail}}</small></button></div></section><Diagnostics :busy="busy||updating||state?.monitor.busy" @action="act"/><SetupGuide :backend="backend" :environment="state?.environment" :busy="busy" @action="act" @refresh="refresh"/><section class="setting-card"><h2> {{tr(`菜单栏与自动读写`)}} </h2><p> {{tr(`关闭窗口后仍在菜单栏运行。设备插入时自动检查并开启 NTFS 读写；退出应用会停止设备检测。`)}} </p><label> {{tr(`插入后自动开启读写`)}} <input type="checkbox" v-model="autoMount" @change="save" /></label><div class="setting-row"><span>{{state?.environment.service?tr(`后台助手已就绪 · 日常挂载无需密码`):tr(`后台助手连接异常`)}}</span></div><p v-if="!state?.environment.service">{{tr(state?.environment.service_issue||'')}}</p><p> {{tr(`安装时如系统提供 Touch ID，可以使用指纹；软件不会保存管理员密码，也不更改系统的验证策略。`)}} </p><p v-if="state?.monitor.last_event"> {{tr(`最近操作：`)}} {{state.monitor.last_event.split('\n')[0]}}</p></section><section class="setting-card"><h2> {{tr(`读写引擎`)}} </h2><p> {{tr(`稳定模式使用 macFUSE 内核后端。首次安装可能需要系统授权和重启。`)}} </p><div class="backend-options" role="group" :aria-label="tr('挂载模式')"><button v-for="b in [{id:'Auto',label:tr('稳定模式（推荐）')},{id:'Kernel',label:tr('内核兼容模式')},{id:'Fskit',label:tr('FSKit（实验性，macOS 15.4+）')},{id:'Microvm',label:tr('微虚拟机（实验性，Apple Silicon · macOS 13+）')}]" :key="b.id" :class="{selected:backend===b.id}" :aria-pressed="backend===b.id" :disabled="busy||state?.monitor.busy||updating" @click="backend=b.id;save()">{{b.label}}</button></div><div v-if="backend==='Microvm'" class="backend-note"><h3>{{tr('免内核扩展 · 离线实验模式')}}</h3><p>{{tr('使用内置 Linux 微虚拟机和本机 NFS，不需要恢复模式或关闭 SIP；仍需后台助手及磁盘访问授权。')}}</p><p>{{tr('磁盘以网络卷显示。Word 直接编辑及大量文件复制存在兼容性限制，重要文件建议先复制到 Mac 再编辑。每个分区的虚拟机内存上限为 512 MiB。')}}</p><p>{{tr('实验模式仅手动挂载，暂停自动开启读写。首次使用建议在测试磁盘上验证。')}}</p><p v-if="!state?.environment.microvm">{{tr('微虚拟机离线组件未安装，请安装完整 PKG')}}</p></div><div class="setting-row"><span>macFUSE {{state?.environment.fuse_version||tr(`尚未安装`)}}</span><button class="secondary" :disabled="busy" @click="act('permissions')"> {{tr(`磁盘访问权限`)}} </button><button class="secondary" :disabled="busy" @click="act('settings')"> {{tr(`系统授权`)}} <ArrowUpRight :size="15"/></button></div></section><section class="setting-card"><h2> {{tr(`磁盘访问授权`)}} </h2><p> {{tr(`macOS 管理员密码与隐私授权分别管理。访问磁盘设备需要为权限助手 ntfs-helper 授予完整磁盘访问。此权限范围较广，请只添加本安装包提供的助手；软件仍只对你选择的外置 NTFS 磁盘执行操作。`)}} </p><p> {{tr(`当前测试版使用临时签名，更新组件后可能需要在系统设置移除旧助手条目，再添加当前助手。授权后重新启动应用。`)}} </p><div class="actions"><button class="secondary" :disabled="busy" @click="act('permissions')"> {{tr(`打开完整磁盘访问`)}} </button><button class="secondary" :disabled="busy" @click="act('permission-helper')"><FolderOpen :size="16"/> {{tr(`打开助手位置`)}} </button></div></section><section class="setting-card"><h2> {{tr(`软件更新`)}} <span class="version">v{{state?.version}}</span></h2><p> {{tr(`启动时及后台定期检查更新。发现新版后暂停新的读写挂载，更新完成后恢复。未检测到必需更新时可离线使用；已经检测到的更新要求会保留。`)}} </p><p> {{tr(`当前应用 v`)}} {{state?.version}} {{tr(`· 已安装助手`)}} {{state?.environment.runtime_version?`v${state.environment.runtime_version}`:tr(`未安装`)}} · {{state?.environment.service?tr(`已连接`):tr(`未连接`)}}</p><p class="update-text">{{updateText||tr(`正在检查更新…`)}}</p><p v-if="update"> {{tr(`点下方按钮下载并验证完整安装包。安装器打开后 macntfs 会退出；按系统提示完成安装，再从「应用程序」启动。首次驱动授权和完整磁盘访问不会被自动绕过。`)}} </p><div class="actions"><button class="secondary" :disabled="updating" @click="updates()"><RefreshCw :size="16"/> {{tr(`检查更新`)}} </button><button v-if="update" class="primary" :disabled="updating||busy||state?.update_blockers>0" @click="installUpdate"><Download :size="16"/> {{updating?tr('正在更新')+' '+progress+'%':tr(`下载并打开安装器`)}}</button></div></section><section class="setting-card"><h2> {{tr(`关于 macntfs`)}} </h2><p> {{tr(`作者：Lucky`)}} </p><p> {{tr(`邮箱：473276@qq.com`)}} </p><p> {{tr(`免费开源 · Rust + Tauri`)}} </p></section></template>
<footer><span class="footer-author"> {{tr(`作者 Lucky · 473276@qq.com`)}} </span><CheckCircle2 :size="14"/> {{busy?tr(`操作处理中，请等待系统响应`):tr(`所有磁盘操作均在本机完成`)}}<span>macOS {{state?.environment.os||'—'}}</span></footer></main>
<div v-if="required" class="update-gate" role="dialog" aria-modal="true" :aria-label="tr('需要更新')"><section class="setting-card"><Download :size="32"/><h2>{{tr('需要更新')}} · v{{required.version}}</h2><p>{{tr('发现新版本后，必须更新才能继续开启读写。已有磁盘不会被强行卸载，可先安全推出。')}}</p><p>{{tr('更新前请先安全推出 macntfs 管理的磁盘；关闭正在使用的文件后重试')}}</p><p>{{tr('安装器需要你的系统授权，完成安装后从「应用程序」重新启动。')}}</p><p v-if="notice" role="alert">{{notice}}</p><button class="primary" :disabled="updating||busy||state?.monitor.busy||state?.update_blockers>0" @click="installUpdate">{{updating?tr('正在更新')+' '+progress+'%':tr('立即更新')}}</button><div class="gate-eject"><button v-for="v in state?.volumes" :key="v.uuid" class="secondary" :disabled="busy||state?.monitor.busy||updating" @click="act('eject',v)">{{tr('安全推出')}} · {{v.name||v.id}}</button></div><button class="secondary" :disabled="updating||busy" @click="invoke('panel_action',{action:'quit'})">{{tr('退出')}}</button></section></div>
</div>
</template>
